import{_ as a,o as i,c as t,a0 as s}from"./chunks/framework.B1UNJuMu.js";const g=JSON.parse('{"title":"Lingue","description":"","frontmatter":{},"headers":[],"relativePath":"it/task/languages.md","filePath":"it/task/languages.md"}'),n={name:"it/task/languages.md"};function o(l,e,d,r,c,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="lingue" tabindex="-1">Lingue <a class="header-anchor" href="#lingue" aria-label="Permalink to &quot;Lingue&quot;">​</a></h1><p>Una gara può avere i testi in più lingue. Gli studenti scelgono la lingua dalla barra di navigazione e possono cambiarla in qualsiasi momento durante la gara, senza perdere le risposte. Tutte le lingue vengono corrette allo stesso modo: per ogni variante c&#39;è un solo insieme di risposte corrette.</p><h2 id="configurazione" tabindex="-1">Configurazione <a class="header-anchor" href="#configurazione" aria-label="Permalink to &quot;Configurazione&quot;">​</a></h2><p>Elenca le lingue <strong>sia</strong> in <code>data/contests.toml</code> <strong>sia</strong> in <code>data/variants.toml</code>, con gli stessi valori. La prima lingua è quella predefinita:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">my-contest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">languages = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;it&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;en&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Le lingue sono codici di due lettere minuscole (<code>it</code>, <code>en</code>, <code>de</code>, ...). Le gare senza <code>languages</code> hanno una sola lingua, <code>it</code>, e funzionano esattamente come prima.</p><h2 id="tradurre-i-problemi" tabindex="-1">Tradurre i problemi <a class="header-anchor" href="#tradurre-i-problemi" aria-label="Permalink to &quot;Tradurre i problemi&quot;">​</a></h2><p>Il testo nella lingua predefinita è sempre <code>question.md</code> (o <code>question.mdx</code>). Ogni traduzione è un file chiamato <code>question.&lt;lingua&gt;.md</code> nella stessa cartella:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>p-1-salto-ostacoli/</span></span>
<span class="line"><span>├── question.md        # lingua predefinita (la prima in \`languages\`)</span></span>
<span class="line"><span>├── question.en.md     # inglese</span></span>
<span class="line"><span>├── fig.asy            # condiviso da tutte le lingue</span></span>
<span class="line"><span>└── variants.py        # condiviso da tutte le lingue</span></span></code></pre></div><p>Una traduzione deve avere <strong>le stesse risposte</strong> del testo predefinito:</p><ul><li>le stesse sottodomande (gli stessi separatori <code>---</code>);</li><li>gli stessi tipi di risposta;</li><li>le stesse opzioni, nello stesso ordine, con le stesse corrette;</li><li>gli stessi valori per le risposte aperte.</li></ul><p><code>quizms variants</code> lo controlla e fallisce se una traduzione viene corretta in modo diverso, per esempio:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✗ The en statement of variant demo/10 doesn&#39;t match the it statement at [&quot;1.2&quot;][&quot;options&quot;][0][&quot;correct&quot;].</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">ATTENZIONE</p><p>Il controllo confronta le risposte, non il testo. Se una traduzione scambia due opzioni sbagliate, il controllo passa, ma la stessa risposta salvata corrisponde a testi diversi nelle due lingue. Mantieni le opzioni nello stesso ordine.</p></div><h3 id="varianti-e-immagini" tabindex="-1">Varianti e immagini <a class="header-anchor" href="#varianti-e-immagini" aria-label="Permalink to &quot;Varianti e immagini&quot;">​</a></h3><p>Tutte le lingue di un problema usano la stessa variante per un dato studente. Le varianti sono definite in ogni file, quindi tutte le traduzioni devono definire <strong>le stesse varianti</strong>, nello stesso ordine. Il modo più semplice è tenerle in un file condiviso, importato da ogni traduzione:</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">import variants from &quot;./variants.py&quot;;</span></span></code></pre></div><p>Le immagini sono importate da ogni file, quindi le traduzioni possono condividerle (<code>![fig](fig.asy)</code>) o usarne una copia tradotta (<code>![fig](fig.en.asy)</code>).</p><h3 id="traduzioni-mancanti" tabindex="-1">Traduzioni mancanti <a class="header-anchor" href="#traduzioni-mancanti" aria-label="Permalink to &quot;Traduzioni mancanti&quot;">​</a></h3><p>Ogni problema usato dalla gara deve avere il testo in ogni lingua: <code>quizms variants</code>, <code>quizms print</code> e <code>quizms firebase import</code> falliscono ed elencano i file mancanti. Le cartelle dei problemi non usate in <code>contest.mdx</code> non vengono controllate.</p><p>L&#39;unica eccezione è <code>quizms dev</code>: una traduzione mancante mostra la lingua predefinita con un avviso, così puoi vedere l&#39;anteprima di una gara mentre è ancora in traduzione.</p><h2 id="tradurre-la-pagina-della-gara" tabindex="-1">Tradurre la pagina della gara <a class="header-anchor" href="#tradurre-la-pagina-della-gara" aria-label="Permalink to &quot;Tradurre la pagina della gara&quot;">​</a></h2><p>Il testo in <code>contest.mdx</code> (titoli delle sezioni, spiegazioni) si traduce con <code>&lt;Locale&gt;</code>:</p><div class="language-mdx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mdx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;Locale lang=&quot;it&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Sezione 1: quiz</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/Locale&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;Locale lang=&quot;en&quot;&gt;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Section 1: quizzes</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/Locale&gt;</span></span></code></pre></div><p><code>&lt;Locale&gt;</code> serve solo per il testo: <code>&lt;Problem&gt;</code> e <code>&lt;Section&gt;</code> non possono stare al suo interno.</p><p>L&#39;intestazione della gara (<code>header</code> in <code>variants.toml</code>, per esempio <code>header.md</code>) si traduce con file <code>header.&lt;lingua&gt;.md</code> nella stessa cartella.</p><h2 id="generare-i-testi" tabindex="-1">Generare i testi <a class="header-anchor" href="#generare-i-testi" aria-label="Permalink to &quot;Generare i testi&quot;">​</a></h2><p><code>quizms variants</code> genera tutte le lingue. Per ogni variante scrive <code>statement.&lt;lingua&gt;.txt</code>, più <code>statement.txt</code> per la lingua predefinita. <code>quizms print</code> scrive <code>statement.&lt;lingua&gt;.pdf</code>, più <code>statement.pdf</code> per la lingua predefinita.</p><p>Entrambi i comandi accettano <code>--languages</code> per generare solo alcune lingue, al posto di quelle configurate. La prima è la lingua predefinita di quell&#39;esecuzione:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">quizms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> variants</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --languages=en</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">quizms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> print</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --languages=it,en</span></span></code></pre></div><p><code>quizms print</code> usa i testi generati da <code>quizms variants</code>, quindi esegui entrambi con le stesse lingue.</p><h2 id="cosa-viene-tradotto" tabindex="-1">Cosa viene tradotto <a class="header-anchor" href="#cosa-viene-tradotto" aria-label="Permalink to &quot;Cosa viene tradotto&quot;">​</a></h2><p>QuizMS traduce il testo fisso che fa parte dei testi: i titoli delle domande (<code>Domanda 1</code> / <code>Question 1</code>), il piè di pagina dei PDF (<code>Variante</code> / <code>Variant</code>), i campi stampati sul PDF (<code>Codice prova</code> / <code>Test code</code>), la nota delle pagine vuote nel PDF dell&#39;insegnante e, nei problemi di <a href="./blockly.html">codice a blocchi</a>, i blocchi predefiniti e le categorie della barra degli strumenti predefinita. Sono disponibili italiano e inglese; le altre lingue usano l&#39;inglese.</p><p>Il testo scritto dall&#39;autore del problema non viene tradotto automaticamente: blocchi personalizzati, barre degli strumenti personalizzate e visualizzatori si possono tradurre importando file diversi in ogni traduzione.</p><p>Il resto dell&#39;interfaccia (menu, pulsanti, messaggi) resta in italiano, così come i valori nei file di configurazione: i nomi delle gare e le etichette dei dati personali (<code>user_data</code>).</p><h2 id="firebase" tabindex="-1">Firebase <a class="header-anchor" href="#firebase" aria-label="Permalink to &quot;Firebase&quot;">​</a></h2><ul><li>La scelta dello studente viene salvata, quindi resta anche dopo aver ricaricato la pagina o cambiato dispositivo. La scelta viene salvata tramite le Cloud Functions di QuizMS, quindi pubblicale dopo aver aggiornato QuizMS: con le funzioni precedenti la scelta non viene salvata.</li><li><code>quizms firebase import</code> controlla che ogni lingua di ogni gara abbia i suoi testi (e i suoi PDF, se sono stati generati) prima di caricarli.</li><li>Gli insegnanti scelgono la lingua dei PDF da scaricare dalla dashboard.</li></ul>`,37)])])}const h=a(n,[["render",o]]);export{g as __pageData,h as default};
